// Package runtime is the generic CRUD engine behind every generated resource
// and data source. A definition (generated into internal/provider by
// tools/sfcgen) names a schema function (generated by tfplugingen-framework)
// and the API operations behind it; this package turns Terraform plan and
// state values into JSON requests and JSON responses back into state,
// without any per-resource code.
package runtime

import (
	"context"

	dsschema "github.com/hashicorp/terraform-plugin-framework/datasource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
)

// Param binds an API parameter to a top-level schema attribute.
type Param struct {
	Name     string // parameter name in the API
	Attr     string // attribute that supplies (or receives) it
	Array    bool   // repeated (form, explode) query parameter
	Required bool
}

// Operation is one HTTP call.
type Operation struct {
	Method string
	// Path may contain {name} placeholders filled from PathParams.
	Path       string
	PathParams []Param
	// Query parameters (data sources).
	Query []Param
	// Body lists the top-level JSON properties sent as the request body.
	// Empty means the operation sends no body.
	Body []string
	// IdempotencyHeader, if set, is sent with a random key so a POST can
	// be retried safely.
	IdempotencyHeader string
}

// ResourceDefinition describes a generated resource.
type ResourceDefinition struct {
	// Name is the type name without the provider prefix, e.g. "pool".
	Name   string
	Schema func(context.Context) schema.Schema

	Create Operation
	Read   Operation
	// Update is nil when the API cannot change the resource in place; every
	// configurable attribute then forces replacement.
	Update *Operation
	Delete Operation
	// BeforeDelete operations run in order before Delete; 404 and 409
	// responses from them are ignored.
	BeforeDelete []Operation
	// DeleteAccept lists additional status codes (besides 404) that mean
	// the delete operation has nothing left to do.
	DeleteAccept []int

	// Spending resources can only be created with allow_spending = true.
	Spending     bool
	SpendingNote string

	// Stable lists computed attributes that never change after creation.
	Stable []string
	// ShapeMismatch lists configurable attributes the API echoes back in a
	// different representation than it accepts (or not at all). Refresh
	// keeps the configured value for them instead of the API's.
	ShapeMismatch []string
	// WorkspaceAttr defaults to the provider's workspace when unset.
	WorkspaceAttr string
	// Renames maps attribute names to JSON property names where they
	// differ, at any nesting depth.
	Renames map[string]string
}

// DataSourceDefinition describes a generated data source.
type DataSourceDefinition struct {
	Name   string
	Schema func(context.Context) dsschema.Schema
	Read   Operation
	// List is set when the response is a {data: [...], has_more} page.
	List bool
	// Paginate follows `cursor` -> `starting_after` until has_more is
	// false (unless the configuration sets a limit or a cursor itself).
	Paginate      bool
	WorkspaceAttr string
	Renames       map[string]string
}
